"""Module for Marvin client settings"""
import platform
import socket
from typing import Optional

KAFKA_SERVERS_DEV = (
    "dev-kafka-1.marvin.ou.nsn-rdnet.net:9092,"
    "dev-kafka-2.marvin.ou.nsn-rdnet.net:9092,"
    "dev-kafka-3.marvin.ou.nsn-rdnet.net:9092"
)
KAFKA_SERVERS_PROD = (
    "otava-kafka-1.marvin.ou.nsn-rdnet.net:9092,"
    "otava-kafka-2.marvin.ou.nsn-rdnet.net:9092,"
    "otava-kafka-3.marvin.ou.nsn-rdnet.net:9092"
)
SUMMARY_VIEW_API_DEV = "http://csv-be-dev.marvin.ou.nsn-rdnet.net:8091"
SUMMARY_VIEW_API_PROD = "http://csv-be.marvin.ou.nsn-rdnet.net:8091"

META_SERVICE_API_DEV = "http://meta-service-dev.marvin.ou.nsn-rdnet.net:9090"
META_SERVICE_API_PROD = "http://meta-service.marvin.ou.nsn-rdnet.net:9090"


class MarvinClientSettings:
    """Marvin client settings class"""

    def __init__(
        self,
        environment: Optional[str] = None,
        kafka_servers: Optional[str] = None,
        summary_view_api: Optional[str] = None,
        meta_service_api: Optional[str] = None,
    ):
        """
        Constructor.
        :param environment: Environment name, e.g. `dev`, `prod`, or None (=local).
        :param kafka_servers: Kafka bootstrap servers, e.g. "server_1:9092,server_2:9092".
        :param summary_view_api: Summary view API URL, e.g. "http://server:8091".
        """
        self.environment = environment
        self.client_host_ip_address = self._get_host_ip_address()
        self.client_host_name = platform.node()

        self.kafka_servers = (
            kafka_servers
            if kafka_servers
            else KAFKA_SERVERS_DEV
            if environment == "dev"
            else KAFKA_SERVERS_PROD
            if environment == "prod"
            else "127.0.0.1:9092"
        )

        self.summary_view_api = (
            summary_view_api
            if summary_view_api
            else SUMMARY_VIEW_API_DEV
            if environment == "dev"
            else SUMMARY_VIEW_API_PROD
            if environment == "prod"
            else "http://127.0.0.1:8091"
        )

        self.meta_service_api = (
            meta_service_api
            if meta_service_api
            else META_SERVICE_API_DEV
            if environment == "dev"
            else META_SERVICE_API_PROD
            if environment == "prod"
            else "http://127.0.0.1:9090"
        )

    @staticmethod
    def _get_host_ip_address() -> str:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)

        try:
            # connect() for UDP doesn't send packets
            addr, port = KAFKA_SERVERS_PROD.split(",")[0].split(":")
            sock.connect((addr, int(port)))
            return sock.getsockname()[0]
        except Exception:
            return "127.0.0.1"
        finally:
            sock.close()
